"""Decision table with version, unit, foresight and refutable claim boundaries."""
import sys,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from p14.common import write,sha,OUT

