 out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=False);rows=[]
 def add(id,claim,kind,version,unit,prospective,conditions,support,gap,status):
  refs={p:sha(ROOT/p) for p in support if (ROOT/p).is_file()}
  rows.append(dict(id=id,claim=claim,category=kind,version=version,independent_unit=unit,prospective=prospective,conditions=conditions,evidence=refs,counterevidence_or_gap=gap,status=status))
 add('P11-M2','M2原留出整程分类31/31一致','empirical_prediction','P11 frozenM2','31 heldout flights, grouped by4 families; not31 unseen conditions',True,'original task, PH0 and initial LP/filter steady approximation',['data/p14-20261027/audit-v1/p11-score-chain.json','docs/THOR_P11_REPORT.md'],'two local first-witness tilt misses and long open replay drift; no hard guarantee','SUPPORTED_ONLY_ORIGINAL_SCOPE')
