 add('P12-PAIR','原严格配对失败混合真实缓存差与保守动作界','design_and_theory','P12 pair-v3','3 development pairs',False,'complete snapshot unavailable',['data/p12-20261026-analysis/pair-feasibility-3.json','docs/THOR_P12_REPORT.md'],'cannot infer paired counterfactual; bound2 alone was not valid reason to deny later randomized mechanism work','LIMITED_NOT_IMPOSSIBILITY')
 add('P12-SCORE','截断任务AGREEMENT缺陷已独立修订','implementation_error','scorev2','7 development flights×6 dependent models',False,'valid prefix witnesses distinguish failure from UNKNOWN',['docs/THOR_P12_SCORE_CORRECTION.md'],'7 uncorrelated-capture forecasts were actual false alarms, not safe incomplete predictions','FIXED_OLD_OUTPUT_RETAINED')
