 add('SOURCE-KERNEL','实测状态/命令给定时源单步核吻合','source_and_numerical','FreeJoint discrete kernel','4 representative development flights',False,'future state at each one-step input; no autonomous claim',['data/p14-20261027/layers-v1/summary.json'],'known-command open error .1m/.15m_s appears17-19s, eventual domain exit; local agreement not global precision','CONDITIONAL_NUMERICAL_SUPPORT')
