 add('P14-MODEL','唯一修正版仍非可靠倾角风险准入','retrospective_prediction','G control and soleM14','66 formal flights in6 dependent blocks;12 dev separate',False,'no fit; old forward results preserved; prospective claim forbidden',['data/p14-20261027/evaluation-v1/summary.json'],'8/14 tilt misses,1/4height miss; no dangerous UNKNOWN substitution; large process error remains','NOT_SAFETY_ADMISSION')
 add('COMBO','F2短组合失败与F4非单调成立于已分块实验','randomized_total_effect','P13 fixed PH1','3 blocks/condition',True,'initial/cache differences retained; sharedNORMAL/A not independent',['docs/THOR_P13_REPORT.md'],'not strict same-initial counterfactual; F4 A itself3 failures; need interpretation by condition','SUPPORTED_SMALL_SAMPLE_FIXED_PLATFORM')
