 add('HEIGHT','恢复充分与必要储备方向不同','theory','P13 maps and P14 exact rational','all-prefix mathematical sequence',False,'net upward acceleration/geometry/cache/execution domain overwholeinterval',['data/p14-20261027/theory-v2/conditional-height.json'],'filter>=871 andtheta cone are not proven reachable under neural feedback; no actual complete certificate','NONEMPTY_ALGEBRAIC_CONDITIONS_ONLY')
